H.background();
const b = P.b, c = P.c, r = P.r, step = Math.max(0, Math.round(P.step));
const q1 = 1;
const q0 = b + r;
const rem = c + r * (b + r);
const w = H.W, h = H.H;
const sg = (x) => (x >= 0 ? "+" : "-");
let y = 96;
const L = 28;
H.text("Polynomial long division", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("(x^2 " + sg(b) + " " + Math.abs(b).toFixed(1) + "x " + sg(c) + " " + Math.abs(c).toFixed(1) + ")  /  (x " + sg(-r) + " " + Math.abs(r).toFixed(1) + ")", 24, 54, { color: H.colors.sub, size: 13 });
const lines = [
  "1) x^2 / x = x   -> first quotient term",
  "2) x*(x " + sg(-r) + " " + Math.abs(r).toFixed(1) + ") = x^2 " + sg(-r) + " " + Math.abs(r).toFixed(1) + "x   subtract",
  "3) bring down: (" + (b + r).toFixed(1) + ")x " + sg(c) + " " + Math.abs(c).toFixed(1),
  "4) (" + (b + r).toFixed(1) + ")x / x = " + (b + r).toFixed(1) + "   -> next term",
  "5) remainder = " + rem.toFixed(1),
];
const lit = step % (lines.length + 1);
for (let i = 0; i < lines.length; i++) {
  const shown = i < lit;
  const pulsing = (i === lit - 1);
  const col = shown ? (pulsing ? H.colors.warn : H.colors.ink) : H.colors.grid;
  if (pulsing) H.rect(L - 6, y - 14, 360, 20, { fill: H.hsl(40, 80, 60, 0.12 + 0.06 * Math.sin(t * 4)) });
  H.text(lines[i], L, y, { color: col, size: 13 });
  y += L;
}
H.rect(L - 6, y + 2, 360, 30, { stroke: H.colors.good, width: 1.5, radius: 6 });
H.text("quotient: x " + sg(q0) + " " + Math.abs(q0).toFixed(1) + "   remainder: " + rem.toFixed(1), L, y + 22, { color: H.colors.good, size: 13, weight: 700 });
const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -12, yMax: 12, box: { x: w * 0.56, y: 80, w: w * 0.40, h: h - 150 } });
v.grid(); v.axes();
const N = (x) => x * x + b * x + c;
v.fn(N, { color: H.colors.accent, width: 2.5 });
v.dot(r, rem, { r: 6 + Math.sin(t * 3), fill: H.colors.warn });
v.line(r, 0, r, rem, { color: H.colors.violet, width: 1, dash: [3, 3] });
H.text("N(r) = remainder = " + rem.toFixed(1), w * 0.56, 70, { color: H.colors.sub, size: 12 });
